class Solution:
    def nextBiggerOnRing(self, ring: List[int]) -> List[int]:
        n = len(ring)
        res, stack = [-1] * n, []
        for i in range(2 * n):
            v = ring[i % n]
            while stack and ring[stack[-1]] < v:
                res[stack.pop()] = v
            if i < n:
                stack.append(i)
        return res

