class Solution {
    public int[] nextBiggerOnRing(int[] ring) {
        int n = ring.length;
        int[] res = new int[n], stack = new int[n];
        Arrays.fill(res, -1);
        int top = 0;
        for (int i = 0; i < 2 * n; i++) {
            int v = ring[i % n];
            while (top > 0 && ring[stack[top - 1]] < v) res[stack[--top]] = v;
            if (i < n) stack[top++] = i;
        }
        return res;
    }
}

