        int n = ring.size();
        vector<int> res(n, -1), stack;
        for (int i = 0; i < 2 * n; i++) {
            int v = ring[i % n];
            while (!stack.empty() && ring[stack.back()] < v) {
                res[stack.back()] = v;
                stack.pop_back();
            }
            if (i < n) stack.push_back(i);
        }
        return res;
    }
};

