int* nextBiggerOnRing(int* ring, int ringSize, int* returnSize) {
    int n = ringSize;
    int* res = malloc(n * sizeof(int));
    int* stack = malloc(n * sizeof(int));
    int top = 0;
    for (int i = 0; i < n; i++) res[i] = -1;
    for (int i = 0; i < 2 * n; i++) {
        int v = ring[i % n];
        while (top > 0 && ring[stack[top - 1]] < v) res[stack[--top]] = v;
        if (i < n) stack[top++] = i;
    }
    free(stack);
    *returnSize = n;
    return res;
}
